// spec: .qa/e2e/specs/post-create.md · seed: tests/seed.free.spec.ts · кейс .qa/tests/post-create/PC-05.md
// @data: идёт в проекте data; устройство — iPhone 13 Mini (WebKit) через test.use ниже.
import { test, expect } from '@playwright/test';
import { saveSession } from '../_shared/session';
import { IPHONE, authFile, cleanupPost, deletePostViaUi, form, isPostPatch, openFeed, postCard, publishPost, qaText, tap, type Published } from './post-helpers';

test.use({ ...IPHONE, storageState: authFile('free') });

test.describe('מסך יצירת פוסט', () => {
  test('Редактирование своего поста: форма заполнена, «שמירה» сохраняет новый текст; затем удаление @iphone @data (#1ff0f4)', async ({ page }) => {
    test.setTimeout(120_000);
    const text = qaText('edit');
    const edited = `${text} edited`;
    let published: Published | undefined;
    let deleted = false;
    try {
      // 1. Свой пост QA-AUTO
      published = await publishPost(page, text);

      // 2. ⋯ → «עריכת הפוסט» → /post/new?id=<id>
      await openFeed(page);
      await tap(page, postCard(page, text).getByRole('button', { name: 'פעולות על הפוסט' }));
      await tap(page, page.getByRole('button', { name: /עריכת הפוסט/ }));
      await page.waitForURL(new RegExp(`/post/new\\?id=${published.id}`));
      const f = form(page);
      // AC6: заголовок «עריכת פוסט», текущий текст в поле, кнопка «שמירה»
      await expect(page.getByText('עריכת פוסט', { exact: true })).toBeVisible();
      await expect(f.text).toHaveValue(text);
      await expect(f.save).toBeEnabled();

      // 3. Изменить и сохранить (AC7)
      await f.text.fill(edited);
      const patchP = page.waitForResponse((r) => isPostPatch(r.request()));
      await tap(page, f.save);
      const patch = await patchP;
      expect(patch.ok(), 'PATCH /rest/v1/posts').toBeTruthy();
      expect(patch.url()).toContain(`id=eq.${published.id}`);
      expect(patch.request().postDataJSON()).toMatchObject({ body: edited });
      await openFeed(page);
      await expect(page.getByText(edited, { exact: true })).toHaveCount(1);
      await expect(page.getByText(text, { exact: true })).toHaveCount(0);
      published.text = edited;

      // 4. Очистка
      await deletePostViaUi(page, edited);
      deleted = true;
    } finally {
      if (published && !deleted) await cleanupPost(page, published);
      await saveSession(page, 'free');
    }
  });
});
